function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 256) return 'words needs 1 to 256 strings.';
  if (words.some(w => typeof w !== 'string' || !/^[a-z]{2}$/.test(w))) return 'Each word is exactly two lowercase letters.';
  if (new Set(words).size !== words.length) return 'The words must all be different.';
  if (new Set(words.join('')).size > 16) return 'All words together may use at most 16 different letters.';
  return null;
}

