function supersequences(words) {
  const id = new Array(26).fill(-1);
  const letters = [];
  for (const word of words) {
    for (const ch of word) {
      const code = ch.charCodeAt(0) - 97;
      if (id[code] === -1) {
        id[code] = letters.length;
        letters.push(code);
      }
    }
  }
  const k = letters.length;
  const before = new Array(k).fill(0);
  for (const word of words) {
    const first = id[word.charCodeAt(0) - 97];
    const second = id[word.charCodeAt(1) - 97];
    before[second] |= 1 << first;
  }
  const total = 1 << k;
  const orderable = new Array(total).fill(false);
  const size = new Array(total).fill(0);
  orderable[0] = true;
  let most = 0;
  for (let once = 1; once < total; once++) {
    size[once] = size[once >> 1] + (once & 1);
    for (let v = 0; v < k; v++) {
      if ((once >> v & 1) === 1 && (before[v] & once) === 0) {
        orderable[once] = orderable[once ^ (1 << v)];
        break;
      }
    }
    if (orderable[once]) {
      most = Math.max(most, size[once]);
    }
  }
  const result = [];
  for (let once = 0; once < total; once++) {
    if (!orderable[once] || size[once] !== most) {
      continue;
    }
    const freq = new Array(26).fill(0);
    for (let v = 0; v < k; v++) {
      freq[letters[v]] = (once >> v & 1) === 1 ? 1 : 2;
    }
    result.push(freq);
  }
  return result;
}

