function supersequences(words) {
  // Try every string over the words' letters, shortest first (all k letters must appear, so start at length k),
  // and collect the letter counts of those that contain every word.
  const letters = [...new Set(words.join(''))];
  const k = letters.length;
  const pairs = words.map(w => [letters.indexOf(w[0]), letters.indexOf(w[1])]);
  for (let length = k; ; length++) {
    const found = new Set();
    const digits = new Array(length).fill(0);
    for (;;) {
      const first = new Array(k).fill(-1), last = new Array(k).fill(-1);
      digits.forEach((d, i) => { if (first[d] < 0) first[d] = i; last[d] = i; });
      // "xy" is a subsequence exactly when the first x comes before the last y.
      if (pairs.every(([x, y]) => first[x] >= 0 && first[x] < last[y])) {
        const freq = new Array(26).fill(0);
        for (const d of digits) freq[letters[d].charCodeAt(0) - 97]++;
        found.add(freq.join(','));
      }
      // Advance to the next string of this length, like an odometer.
      let i = 0;
      while (i < length && digits[i] === k - 1) digits[i++] = 0;
      if (i === length) break;
      digits[i]++;
    }
    if (found.size) return [...found].map(key => key.split(',').map(Number));
  }
}

