function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const shuffle = list => { for (let i = list.length - 1; i > 0; i--) { const j = pick(i + 1); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const large = size === 'large';
  // Small inputs use at most 4 letters so the brute force can try every string; large ones use 16.
  const k = large ? 16 : 1 + pick(4);
  const letters = shuffle('abcdefghijklmnopqrstuvwxyz'.split('')).slice(0, k);
  const loop = large ? rand() * 0.15 : rand() * 0.4;
  const edge = large ? 0.1 + rand() * 0.65 : 0.1 + rand() * 0.7;
  const words = new Set();
  for (const x of letters) for (const y of letters) if (rand() < (x === y ? loop : edge)) words.add(x + y);
  // Large inputs use all 16 letters: a letter left out gets a word with the next letter.
  if (large) letters.forEach((x, i) => { if (![...words].some(w => w.includes(x))) words.add(x + letters[(i + 1) % k]); });
  if (words.size === 0) words.add(letters[pick(k)] + letters[pick(k)]);
  return [shuffle([...words])];
}
